        const marketId = market['id'];
        const loc = this.safeString(params, 'loc', 'us');
        const method = this.safeString(params, 'method', 'marketPublicGetV1beta3CryptoLocBars');
        const request = {
            'symbols': marketId,
            'loc': loc,
        };
